import { shallowRef } from 'vue'

const controller = window.JuraganAppearance
export const appearance = shallowRef(controller.getState())
export const themes = controller.themes
export const setAppearance = controller.setPreferences
const unsubscribe = controller.subscribe((state) => {
	appearance.value = state
})
if (import.meta.hot) import.meta.hot.dispose(unsubscribe)
